using System;using System.Data;public partial class Login:System.Web.UI.Page{public string st="";protected void Page_Load(object sender,EventArgs e){if(Page.IsPostBack){try{string u=MyAdoHelper.FixText(Request.Form["userName"]),p=MyAdoHelper.FixText(Request.Form["password"]);if(u==""||p==""){st="יש למלא שם משתמש וסיסמה";return;}DataTable dt=MyAdoHelper.ExecuteDataTable("SELECT * FROM Users WHERE UserName=N'"+u+"' AND Password=N'"+p+"'");if(dt.Rows.Count==0){st="שם המשתמש או הסיסמה אינם נכונים";return;}Session["user"]="ok";Session["userId"]=dt.Rows[0]["UserId"].ToString();Session["userName"]=dt.Rows[0]["UserName"].ToString();Session["nickName"]=dt.Rows[0]["NickName"].ToString();Session["userType"]=dt.Rows[0]["UserType"].ToString();Session["coins"]=dt.Rows[0]["Coins"].ToString();Response.Redirect("Home.aspx");}catch(Exception){st="לא ניתן להתחבר למסד הנתונים. יש לנסות שוב.";}}}}